def shell(title,body,scripts='',style=''):
 return '<!doctype html><html lang="zh-SG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · 华文通</title><link rel="stylesheet" href="'+shared+'style.css?v='+V+'"><link rel="stylesheet" href="lesson.css?v='+V+'">'+style+'</head><body><header class="site-header"><a href="../../../../../index.html#2/texts"><img src="../../../../../assets/huawentong-logo.png" alt="华文通"></a><span>'+L['label']+'</span></header>'+body+scripts+'</body></html>'
home='''<main><p class="crumb">中二高级华文 / 课文学习 / 单元六</p><section class="hero"><div><p class="eyebrow">核心课文 · 2—3课时</p><h1>多元而开放的<br>新加坡</h1><p class="lead">读懂事例，解释它怎样支持观点。</p><div class="actions"><a class="btn primary" href="reading.html">开始／继续学习</a><a class="btn" href="reading.html#words">我的词语本</a></div></div><img class="hero-image" src="assets/comic1.png" alt="保留原有漫画第一页面貌"></section><div class="cards"><article class="card"><h2>第一课</h2><p>第1—4段<br>地理、贸易与族群形成</p><a class="btn" href="reading.html#paragraph-1">进入图文</a></article><article class="card"><h2>第二课</h2><p>第5—7段<br>生活、艺术与全文结构</p><a class="btn" href="reading.html#paragraph-5">进入图文</a></article><article class="card"><h2>第三课</h2><p>四字短语、开放回应<br>当堂检查与订正</p><a class="btn" href="reading.html#lesson3">进入任务</a></article></div><div class="actions footer-note"><a class="btn" href="comics.html">全文与漫画回读</a><a class="btn" href="reading.html#review">学习记录</a><a class="btn" href="teacher.html">教师资料与下载</a></div></main>'''
(R/'index.html').write_text(shell(L['title'],home))
read='''<nav class="nav"><a class="btn" href="index.html">主页</a><button data-view="read">读文</button><button data-view="lesson1">第一课</button><button data-view="lesson2">第二课</button><button data-view="lesson3">第三课</button><button data-view="review">检查</button><button id="wordList">词语本</button></nav><details class="identity-banner"><summary>姓名与班级</summary><div id="topIdentity" class="identity"></div></details><main><p id="saveState" class="muted" role="status"></p><div id="readTask" class="workspace"><article id="source" class="paper"></article><section id="activity" class="paper"></section></div><section id="review" class="paper" hidden></section><dialog id="dialog"><button id="dialogClose" class="dialog-close">关闭</button><div id="dialogContent"></div></dialog><dialog id="wordDialog"><button id="wordDialogClose" class="dialog-close">关闭</button><div id="wordDialogContent"></div></dialog></main>'''
scripts=''.join('<script src="'+p+'?v='+V+'"></script>' for p in ['content.js','lexicon.js',shared+'catalog.js',shared+'wordbook.js',shared+'app.js','identity.js','lesson-ui.js'])
