ui=r'''(()=>{'use strict';const L=window.LESSON,A=document.querySelector('#activity'),S=document.querySelector('#source'),K='huawentong-lesson-'+L.id+'-v1';
function go(h){window.speechSynthesis?.cancel();location.hash=h;window.scrollTo({top:0,behavior:'instant'})}
function enhance(){const state=window.LessonEngine.state();if(state.position.view==='read'){const p=state.position.p;const next=document.querySelector('#nextPara');next.textContent='本段问题';next.onclick=()=>go('task-'+L.paragraphTasks[p-1]);if(!A.querySelector('.panel-nav')){const list=A.querySelector('.panel-list'),panels=[...list.querySelectorAll('.panel')];if(panels.length>1){state.picturePositions=state.picturePositions||{};let index=Math.min(panels.length-1,state.picturePositions[p]||0);const nav=document.createElement('div');nav.className='panel-nav';const prev=document.createElement('button'),label=document.createElement('span'),forward=document.createElement('button');prev.textContent='上一格';forward.textContent='下一格';nav.append(prev,label,forward);list.after(nav);const show=()=>{panels.forEach((n,i)=>n.hidden=i!==index);prev.disabled=index===0;forward.disabled=index===panels.length-1;label.textContent='本段漫画 '+(index+1)+' / '+panels.length;state.picturePositions[p]=index;try{localStorage.setItem(K,JSON.stringify(state))}catch{}};prev.onclick=()=>{index--;show()};forward.onclick=()=>{index++;show()};show();}}if(!A.querySelector('.word-support')){const section=document.createElement('section');section.className='word-support';const h=document.createElement('b');h.textContent='本段词语';section.append(h);for(const[w,v]of Object.entries(window.LESSON_WORDS)){if(v.paragraph!==p)continue;const b=document.createElement('button');b.className='word';b.dataset.word=w;b.textContent=w;section.append(b)}A.querySelector('.word-add-row').before(section)}}
if(state.position.view==='task'){const t=L.tasks[state.position.task],next=document.querySelector('#nextTask'),after={'p1-view':2,'p2-coins':3,'p3-relation':4,'p4-open':5,'p5-link':6,'p6-art':7};if(after[t.id]){next.textContent='继续读第'+after[t.id]+'段';next.onclick=()=>go('paragraph-'+after[t.id])}if(!A.querySelector('.sequence-nav')){const d=document.createElement('div');d.className='sequence-nav';const a=document.createElement('a');a.className='btn';a.href='#paragraph-'+t.focus[0];a.textContent='回到图文';d.append(a);A.querySelector('.task-footer').before(d)}}}
const observer=new MutationObserver(()=>{observer.disconnect();enhance();watch()});function watch(){observer.observe(A,{childList:true});observer.observe(S,{childList:true})}enhance();watch();})();'''
(R/'lesson-ui.js').write_text(ui)
body='<nav class="nav"><a class="btn" href="index.html">课文主页</a><a class="btn" href="reading.html">互动学习</a></nav><main><h1>全文与漫画回读</h1><p>漫画帮助理解，作答依据回到原文。</p>'+''.join('<section class="text-full"><h2>第'+str(i+1)+'段</h2><p>'+E(p)+'</p></section>' for i,p in enumerate(L['paragraphs']))+''.join('<figure class="comic-source"><img loading="lazy" src="assets/comic'+str(i)+'.png" alt="原有漫画第'+str(i)+'页"><figcaption>原有漫画第'+str(i)+'页 · 原图保留</figcaption></figure>' for i in range(1,6))+'</main>'
(R/'comics.html').write_text(shell('全文与漫画回读',body))
flow=[('第一课 50分钟','导入与第1段8分钟；第2段14分钟；第3段14分钟；第4段10分钟；整理与口头回顾4分钟。'),('第二课 50分钟','第5段12分钟；第6段20分钟；第7段8分钟；全文结构10分钟。'),('第三课 50分钟','课本词语5分钟；四字短语12分钟；语境用词8分钟；开放回应18分钟；订正和词语本7分钟。'),('两课时压缩 100分钟','第一课按上述第一课流程完成第1—4段，共50分钟。第二课：第5—7段及结构22分钟，课本词语3分钟，四字短语6分钟，语境用词4分钟，开放题12分钟，订正3分钟。压缩口头汇报，保留原题与开放回应；学生需要更多支架时采用三课时。')]
teacher='<nav class="nav"><a class="btn" href="index.html">课文主页</a><a class="btn" href="projection.html">在线投影</a></nav><main><h1>教师资料</h1><p>《多元而开放的新加坡》 · 中二高级华文单元六</p><section class="teacher-section"><h2>配套下载</h2><div class="actions"><button id="downloadPpt" class="btn">可编辑PPT</button><a class="btn" href="downloads/teacher-guide.docx" download>教学流程与参考答案</a><button id="downloadPackage" class="btn">整套教学包</button><button id="downloadOffline" class="btn">离线学习包</button></div><p id="packageStatus" role="status"></p><p>整套包附课件字体；在线投影无需安装字体。</p></section><section class="teacher-section"><h2>教学目标</h2><p>理解七段内容及全文结构；解释事例与作者观点的联系；具体分析第五段的过渡作用；运用四字短语，并以具体例子说明多元与开放。</p><h2>课时流程</h2>'+''.join('<h3>'+a+'</h3><p>'+b+'</p>' for a,b in flow)+'<h2>材料与记录</h2><p>依据教师上传的课文、课本问题、教参及五页原漫画。历史说法按课文理解，不把漫画当作实物史料。网页记录保存在同域、同设备、同浏览器，可导出逐题CSV和完整JSON；没有自动上传教师或Google Sheet，也没有账号云同步。词语本跨已接入华文通的课文汇总个人收藏。</p><p>课堂不设倒计时、速度分或排行榜。首次答错先提示，5秒后可订正；主观题需教师按意义点覆核。</p><h2>旧资源整合</h2><p>旧综合学习单与随堂题库中的重复观点题、钱币题、排序题与词语题合并。本课采用新的稳定题目ID，不把旧版分数套到新题。两个旧学生入口改为新入口引导，旧源文件归档，既有后台数据保留。</p></section>'
for t in L['tasks']:
 teacher+='<section class="teacher-section"><h2>'+E(t['title'])+'</h2><p class="guide">'+E(t['source']+' · '+t['role'])+'</p><p class="question">'+E(t['questions'][0])+'</p><h3>参考答案</h3><p class="answer-model">'+E(t['answer'])+'</p><h3>Direct Info 与必要加工</h3><p>'+E(t['explain'])+'</p><h3>核对要点</h3><ul>'+''.join('<li>'+E(p)+'</li>' for p in t['points'])+'</ul><p>'+E(t['scoreGuide'])+'</p><details><summary>提示与常见误区</summary><p>'+E('提示一：'+t['hints'][0])+'</p><p>'+E('提示二：'+t['hints'][1])+'</p><p>'+E(t['reject'])+'</p></details></section>'
teacher+='</main>'
(R/'teacher.html').write_text(shell('教师教学流程与答案',teacher,'<script src="pack.js"></script>'))
proj='<nav class="nav"><a class="btn" href="teacher.html">教师资料</a><a class="btn" href="reading.html">学生学习</a></nav><main><h1>课堂投影</h1><div class="projection-controls"><button data-lesson="1">第一课</button><button data-lesson="2">第二课</button><button data-lesson="3">第三课</button><button id="prev">上一页</button><select id="slideSelect" aria-label="选择投影页"></select><button id="next">下一页</button><button id="full">全屏</button></div><section class="projector" id="projector"><img id="slideImage" alt="课堂投影"><div class="projection-controls"><span id="counter" style="color:white"></span></div></section><details class="slide-notes"><summary>教师提示</summary><p id="notes"></p></details></main>'
(R/'projection.html').write_text(shell('在线投影',proj,'<script src="projection.js?v='+V+'"></script>'))
(R/'projection.js').write_text("fetch('slides/slides.json').then(r=>{if(!r.ok)throw Error('资源加载失败');return r.json()}).then(slides=>{const $=s=>document.querySelector(s),sel=$('#slideSelect');let n=Math.max(0,Math.min(slides.length-1,Number(location.hash.slice(1)||1)-1));slides.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=(i+1)+' '+s.title;sel.append(o)});function draw(){const s=slides[n];$('#slideImage').src=s.image;$('#slideImage').alt=s.title;$('#notes').textContent=s.notes;$('#counter').textContent=(n+1)+' / '+slides.length;sel.value=n;$('#prev').disabled=n===0;$('#next').disabled=n===slides.length-1;history.replaceState(null,'','#'+(n+1))}document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{n=slides.findIndex(s=>s.lesson===+b.dataset.lesson);draw()});$('#prev').onclick=()=>{if(n>0){n--;draw()}};$('#next').onclick=()=>{if(n<slides.length-1){n++;draw()}};sel.onchange=()=>{n=+sel.value;draw()};$('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():$('#projector').requestFullscreen?.();document.onkeydown=e=>{if(e.target.matches('select,input,textarea'))return;if(e.key==='ArrowRight'&&n<slides.length-1){n++;draw()}if(e.key==='ArrowLeft'&&n>0){n--;draw()}};draw()}).catch(e=>document.querySelector('#notes').textContent='投影暂未加载，请刷新或下载PPT。');")
(R/'README.txt').write_text('多元而开放的新加坡 教学配套\n中二高级华文 单元六 核心课文\n\n学生：打开index.html或reading.html。\n教师：teacher.html、projection.html，下载区含可编辑PPT及教师DOCX。\n原漫画五页40格保持不变，按七段对应。\n学习记录保存在当前设备与浏览器，未自动上传教师或Google Sheet。\n首次答案、订正、逐题CSV、完整JSON可导出。个人词语本与本课答案分别存储。\n主观题由教师覆核，不自动判分。\n离线包解压后打开index.html。离线与线上记录分开；词语本可导出导入，作答记录可导出留存。\n教师原文及题目来源：本轮上传课本与教学参考截图。历史陈述按课文理解。\n')
